INSERT INTO public.places VALUES ('d83ee730-b720-40b5-b301-c580a0158a8e', 'Colosseum', 41.8909421, 12.491903, '0101000020E6100000CC9BC3B5DAFB2840951007640AF24440', '{"type": "pedestrian", "class": "highway", "address": {"city": "Roma", "road": "Colosseo", "state": "Lazio", "county": "Roma Capitale", "suburb": "Municipio Roma I", "country": "Italia", "quarter": "Celio", "postcode": "00184", "country_code": "it", "ISO3166-2-lvl4": "IT-62", "ISO3166-2-lvl6": "IT-RM"}, "extratags": {"lit": "yes", "phone": "+39 06 3996 7700", "surface": "sett", "website": "https://parcocolosseo.it/", "wikipedia": "it:Colosseo", "smoothness": "intermediate", "description": "Dal 18 ottobre 2023 il biglietto sarà nominativo.", "opening_hours": "Nov 01-Feb 15: 08:30-16:30; Feb 16-Mar 31: 08:30-17:00; Apr-Aug: 08:30-19:15; Sep: 08:30-19:00; Oct 08:30-18:30; May 01 off; Jan 01 off; Dec 25 off", "contact:facebook": "parcocolosseo", "wikimedia_commons": "Category:Colosseum"}, "country_code": "it", "wikipedia_summary": "The Colosseum is an elliptical amphitheatre in the centre of the city of Rome, Italy, just east of the Roman Forum. It is the largest ancient amphitheatre ever built, and is the largest standing amphitheatre in the world. Construction began under the Emperor Vespasian in 72 and was completed in AD 80 under his successor and heir, Titus. Further modifications were made during the reign of Domitian. The three emperors who were patrons of the work are known as the Flavian dynasty, and the amphitheatre was named the Flavian Amphitheatre by later classicists and archaeologists for its association with their family name (Flavius).", "enrichment_timestamp": "2025-10-23T05:15:24.750Z"}', '[-0.044563595,-0.029642617,0.08897283,0.042484984,-0.012819935,0.013236986,0.014242793,0.03652254,0.0094815,-0.033239767,0.0043121376,-0.07266898,0.02925463,0.056596044,-0.012618486,-0.016547926,0.01059445,0.05212419,-0.009972914,0.005201359,0.087254,-0.034720726,0.027943825,-0.09653895,-0.0109800305,0.0